'use client';

/**
 * ZkProofFlow — W11-CAR-013
 *
 * Replaces the former hardcoded mock proof (which resolved a fake proof
 * string after a 2-second setTimeout) with a real UltraHonk ZK-SNARK
 * generated by the Barretenberg backend (@aztec/bb.js) running inside a
 * Web Worker so the main thread / UI remains responsive.
 *
 * Architecture
 * ────────────
 *  ┌────────────────────┐  postMessage(GENERATE_PROOF)  ┌──────────────────────┐
 *  │  ZkProofFlow (UI)  │ ───────────────────────────►  │  zk-proof.worker.js  │
 *  │  (main thread)     │ ◄───────────────────────────  │  (worker thread)     │
 *  └────────────────────┘  PROOF_PROGRESS / RESULT /    └──────────────────────┘
 *                          PROOF_ERROR                   • noir_wasm compile
 *                                                        • bb.js UltraHonk
 *
 * Usage
 * ─────
 *   <ZkProofFlow
 *     circuitSource={ZK_COMPLY_CIRCUIT_SOURCE}
 *     kycLevel={identity.kycLevel}
 *     countryCode={identity.countryCode}
 *     salt={salt}
 *     requiredKyc={requiredKyc}
 *     allowedCountry={allowedCountry}
 *     onResult={handleResult}
 *     onError={handleError}
 *   />
 */

import React, { useEffect, useRef, useState } from 'react';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ZkProofRequest {
  /** Noir circuit source code — bundled constant, no network fetch needed. */
  circuitSource: string;
  kycLevel: number;
  countryCode: number;
  /** Decimal string representation of a 32-byte salt (bigint-safe). */
  salt: string;
  requiredKyc: number;
  allowedCountry: number;
}

export interface ZkProofResult {
  /** Hex-encoded UltraHonk proof bytes. */
  proofHex: string;
  /** Hex-encoded flattened public inputs. */
  publicInputsHex: string;
  /** Hex-encoded verification key. */
  vkHex: string;
  /** 32-byte Poseidon2 nullifier (hex). Prevents double-spend. */
  nullifierHex: string;
  /** 32-byte Poseidon2 credential commitment (hex). */
  commitmentHex: string;
}

interface WorkerMessage {
  type: 'PROOF_PROGRESS' | 'PROOF_RESULT' | 'PROOF_ERROR';
  payload: unknown;
}

export interface ZkProofFlowProps extends ZkProofRequest {
  onResult: (result: ZkProofResult) => void;
  onError: (message: string) => void;
  /** Optional render-prop for a custom progress UI. */
  renderProgress?: (step: string) => React.ReactNode;
}

// ---------------------------------------------------------------------------
// Default progress UI
// ---------------------------------------------------------------------------

function DefaultProgress({ step }: { step: string }) {
  return (
    <div
      role="status"
      aria-live="polite"
      aria-label="ZK proof generation in progress"
      className="flex flex-col items-center gap-4 py-8 text-center"
    >
      {/* Spinner */}
      <svg
        className="h-10 w-10 animate-spin text-primary"
        xmlns="http://www.w3.org/2000/svg"
        fill="none"
        viewBox="0 0 24 24"
        aria-hidden="true"
      >
        <circle
          className="opacity-25"
          cx="12"
          cy="12"
          r="10"
          stroke="currentColor"
          strokeWidth="4"
        />
        <path
          className="opacity-75"
          fill="currentColor"
          d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"
        />
      </svg>

      <p className="text-sm font-medium text-foreground">Generating ZK proof…</p>
      <p className="text-xs text-muted-foreground">{step}</p>

      <p className="max-w-xs text-xs text-muted-foreground">
        This runs entirely in your browser. Your credentials are never sent
        to any server.
      </p>
    </div>
  );
}

// ---------------------------------------------------------------------------
// ZkProofFlow component
// ---------------------------------------------------------------------------

/**
 * Mounts a Web Worker that computes a real UltraHonk ZK-SNARK proof over
 * the supplied credentials.  Calls `onResult` on success or `onError` on
 * failure.  The worker is terminated on unmount.
 *
 * React.StrictMode double-mount is guarded by the `started` ref so the
 * worker is only spawned once per logical mount.
 */
export function ZkProofFlow({
  circuitSource,
  kycLevel,
  countryCode,
  salt,
  requiredKyc,
  allowedCountry,
  onResult,
  onError,
  renderProgress,
}: ZkProofFlowProps) {
  const [step, setStep] = useState('Initialising…');
  const workerRef = useRef<Worker | null>(null);
  const startedRef = useRef(false);

  useEffect(() => {
    // Guard against StrictMode double-invoke
    if (startedRef.current) return;
    startedRef.current = true;

    // Spawn worker — the file lives in /public so it is served as a static
    // asset at runtime.  We use type:'module' so the worker can use
    // dynamic import() for the heavy WASM packages.
    const worker = new Worker('/zk-proof.worker.js', { type: 'module' });
    workerRef.current = worker;

    worker.addEventListener('message', (event: MessageEvent<WorkerMessage>) => {
      const { type, payload } = event.data;

      switch (type) {
        case 'PROOF_PROGRESS':
          setStep((payload as { step: string }).step);
          break;

        case 'PROOF_RESULT':
          worker.terminate();
          workerRef.current = null;
          onResult(payload as ZkProofResult);
          break;

        case 'PROOF_ERROR':
          worker.terminate();
          workerRef.current = null;
          onError((payload as { message: string }).message);
          break;
      }
    });

    worker.addEventListener('error', (event: ErrorEvent) => {
      worker.terminate();
      workerRef.current = null;
      onError(event.message ?? 'Unknown worker error');
    });

    // Send the proof request to the worker
    worker.postMessage({
      type: 'GENERATE_PROOF',
      payload: {
        circuitSource,
        kycLevel,
        countryCode,
        salt,
        requiredKyc,
        allowedCountry,
      } satisfies ZkProofRequest,
    });

    return () => {
      // Terminate on unmount (or StrictMode cleanup before re-mount)
      if (workerRef.current) {
        workerRef.current.terminate();
        workerRef.current = null;
      }
      // Allow re-start if the component remounts with new props
      startedRef.current = false;
    };
  }, [
    circuitSource,
    kycLevel,
    countryCode,
    salt,
    requiredKyc,
    allowedCountry,
    onResult,
    onError,
  ]);

  return (
    <>
      {renderProgress ? renderProgress(step) : <DefaultProgress step={step} />}
    </>
  );
}
